use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclenum! {
# [derive (Clone , Encodable , Decodable , Debug)] pub enum ExprKind { # [doc = " An array (e.g, `[a, b, c, d]`)."] Array (ThinVec < Box < Expr > >) , # [doc = " Allow anonymous constants from an inline `const` block."] ConstBlock (AnonConst) , # [doc = " A function call."] # [doc = ""] # [doc = " The first field resolves to the function itself,"] # [doc = " and the second field is the list of arguments."] # [doc = " This also represents calling the constructor of"] # [doc = " tuple-like ADTs such as tuple structs and enum variants."] Call (Box < Expr > , ThinVec < Box < Expr > >) , # [doc = " A method call (e.g., `x.foo::<Bar, Baz>(a, b, c)`)."] MethodCall (Box < MethodCall >) , # [doc = " A tuple (e.g., `(a, b, c, d)`)."] Tup (ThinVec < Box < Expr > >) , # [doc = " A binary operation (e.g., `a + b`, `a * b`)."] Binary (BinOp , Box < Expr > , Box < Expr >) , # [doc = " A unary operation (e.g., `!x`, `*x`)."] Unary (UnOp , Box < Expr >) , # [doc = " A literal (e.g., `1`, `\"foo\"`)."] Lit (token :: Lit) , # [doc = " A cast (e.g., `foo as f64`)."] Cast (Box < Expr > , Box < Ty >) , # [doc = " A type ascription (e.g., `builtin # type_ascribe(42, usize)`)."] # [doc = ""] # [doc = " Usually not written directly in user code but"] # [doc = " indirectly via the macro `type_ascribe!(...)`."] Type (Box < Expr > , Box < Ty >) , # [doc = " A `let pat = expr` expression that is only semantically allowed in the condition"] # [doc = " of `if` / `while` expressions. (e.g., `if let 0 = x { .. }`)."] # [doc = ""] # [doc = " `Span` represents the whole `let pat = expr` statement."] Let (Box < Pat > , Box < Expr > , Span , Recovered) , # [doc = " An `if` block, with an optional `else` block."] # [doc = ""] # [doc = " `if expr { block } else { expr }`"] # [doc = ""] # [doc = " If present, the \"else\" expr is always `ExprKind::Block` (for `else`) or"] # [doc = " `ExprKind::If` (for `else if`)."] If (Box < Expr > , Box < Block > , Option < Box < Expr > >) , # [doc = " A while loop, with an optional label."] # [doc = ""] # [doc = " `'label: while expr { block }`"] While (Box < Expr > , Box < Block > , Option < Label >) , # [doc = " A `for` loop, with an optional label."] # [doc = ""] # [doc = " `'label: for await? pat in iter { block }`"] # [doc = ""] # [doc = " This is desugared to a combination of `loop` and `match` expressions."] ForLoop { pat : Box < Pat > , iter : Box < Expr > , body : Box < Block > , label : Option < Label > , kind : ForLoopKind , } , # [doc = " Conditionless loop (can be exited with `break`, `continue`, or `return`)."] # [doc = ""] # [doc = " `'label: loop { block }`"] Loop (Box < Block > , Option < Label > , Span) , # [doc = " A `match` block."] Match (Box < Expr > , ThinVec < Arm > , MatchKind) , # [doc = " A closure (e.g., `move |a, b, c| a + b + c`)."] Closure (Box < Closure >) , # [doc = " A block (`'label: { ... }`)."] Block (Box < Block > , Option < Label >) , # [doc = " An `async` block (`async move { ... }`),"] # [doc = " or a `gen` block (`gen move { ... }`)."] # [doc = ""] # [doc = " The span is the \"decl\", which is the header before the body `{ }`"] # [doc = " including the `asyng`/`gen` keywords and possibly `move`."] Gen (CaptureBy , Box < Block > , GenBlockKind , Span) , # [doc = " An await expression (`my_future.await`). Span is of await keyword."] Await (Box < Expr > , Span) , # [doc = " A use expression (`x.use`). Span is of use keyword."] Use (Box < Expr > , Span) , # [doc = " A try block (`try { ... }`)."] TryBlock (Box < Block >) , # [doc = " An assignment (`a = foo()`)."] # [doc = " The `Span` argument is the span of the `=` token."] Assign (Box < Expr > , Box < Expr > , Span) , # [doc = " An assignment with an operator."] # [doc = ""] # [doc = " E.g., `a += 1`."] AssignOp (AssignOp , Box < Expr > , Box < Expr >) , # [doc = " Access of a named (e.g., `obj.foo`) or unnamed (e.g., `obj.0`) struct field."] Field (Box < Expr > , Ident) , # [doc = " An indexing operation (e.g., `foo[2]`)."] # [doc = " The span represents the span of the `[2]`, including brackets."] Index (Box < Expr > , Box < Expr > , Span) , # [doc = " A range (e.g., `1..2`, `1..`, `..2`, `1..=2`, `..=2`; and `..` in destructuring assignment)."] Range (Option < Box < Expr > > , Option < Box < Expr > > , RangeLimits) , # [doc = " An underscore, used in destructuring assignment to ignore a value."] Underscore , # [doc = " Variable reference, possibly containing `::` and/or type"] # [doc = " parameters (e.g., `foo::bar::<baz>`)."] # [doc = ""] # [doc = " Optionally \"qualified\" (e.g., `<Vec<T> as SomeTrait>::SomeType`)."] Path (Option < Box < QSelf > > , Path) , # [doc = " A referencing operation (`&a`, `&mut a`, `&raw const a` or `&raw mut a`)."] AddrOf (BorrowKind , Mutability , Box < Expr >) , # [doc = " A `break`, with an optional label to break, and an optional expression."] Break (Option < Label > , Option < Box < Expr > >) , # [doc = " A `continue`, with an optional label."] Continue (Option < Label >) , # [doc = " A `return`, with an optional value to be returned."] Ret (Option < Box < Expr > >) , # [doc = " Output of the `asm!()` macro."] InlineAsm (Box < InlineAsm >) , # [doc = " An `offset_of` expression (e.g., `builtin # offset_of(Struct, field)`)."] # [doc = ""] # [doc = " Usually not written directly in user code but"] # [doc = " indirectly via the macro `core::mem::offset_of!(...)`."] OffsetOf (Box < Ty > , Vec < Ident >) , # [doc = " A macro invocation; pre-expansion."] MacCall (Box < MacCall >) , # [doc = " A struct literal expression."] # [doc = ""] # [doc = " E.g., `Foo {x: 1, y: 2}`, or `Foo {x: 1, .. rest}`."] Struct (Box < StructExpr >) , # [doc = " An array literal constructed from one repeated element."] # [doc = ""] # [doc = " E.g., `[1; 5]`. The expression is the element to be"] # [doc = " repeated; the constant is the number of times to repeat it."] Repeat (Box < Expr > , AnonConst) , # [doc = " No-op: used solely so we can pretty-print faithfully."] Paren (Box < Expr >) , # [doc = " A try expression (`expr?`)."] Try (Box < Expr >) , # [doc = " A `yield`, with an optional value to be yielded."] Yield (YieldKind) , # [doc = " A `do yeet` (aka `throw`/`fail`/`bail`/`raise`/whatever),"] # [doc = " with an optional value to be returned."] Yeet (Option < Box < Expr > >) , # [doc = " A tail call return, with the value to be returned."] # [doc = ""] # [doc = " While `.0` must be a function call, we check this later, after parsing."] Become (Box < Expr >) , # [doc = " Bytes included via `include_bytes!`"] # [doc = ""] # [doc = " Added for optimization purposes to avoid the need to escape"] # [doc = " large binary blobs - should always behave like [`ExprKind::Lit`]"] # [doc = " with a `ByteStr` literal."] # [doc = ""] # [doc = " The value is stored as a `ByteSymbol`. It's unfortunate that we need to"] # [doc = " intern (hash) the bytes because they're likely to be large and unique."] # [doc = " But it's necessary because this will eventually be lowered to"] # [doc = " `LitKind::ByteStr`, which needs a `ByteSymbol` to impl `Copy` and avoid"] # [doc = " arena allocation."] IncludedBytes (ByteSymbol) , # [doc = " A `format_args!()` expression."] FormatArgs (Box < FormatArgs >) , UnsafeBinderCast (UnsafeBinderCastKind , Box < Expr > , Option < Box < Ty > >) , # [doc = " Placeholder for an expression that wasn't syntactically well formed in some way."] Err (ErrorGuaranteed) , # [doc = " Acts as a null expression. Lowering it will always emit a bug."] Dummy , }
}